from helpers import D, src, DSM, mk
from functools import partial
CARDS = []
P = partial(mk, "personality", "personality", "fingerprint")
DSM_P = DSM("Personality Disorders")
NIMH_PD = src("src-nimh-pd", "Personality Disorders statistics", "National Institute of Mental Health (NIMH)", "https://www.nimh.nih.gov/health/statistics/personality-disorders", seen=True)
NESARC = src("src-nesarc-pd", "Prevalence, correlates, and disability of personality disorders in the United States (NESARC)", "Journal of Clinical Psychiatry (Grant et al.); summarized in Psychiatric News", "https://psychnews.psychiatryonline.org/doi/10.1176/pn.39.17.0390012", 2004, seen=True)
NICE78 = src("src-nice-cg78", "Borderline personality disorder: recognition and management (CG78)", "NICE", "https://www.nice.org.uk/guidance/cg78", 2009, seen=True)
NICE77 = src("src-nice-cg77", "Antisocial personality disorder: prevention and management (CG77)", "NICE", "https://www.nice.org.uk/guidance/cg77", 2009, note="Not opened.")
PD_NOTE = "All personality disorder cards are flagged for clinician review because of stigma risk."
PD_COMMS = ["mind-side-by-side", "sane-forums-australia"]

CARDS.append(P("about-personality-disorders", "Personality Disorders (explainer)", "What the label means, and why it's controversial", ["PD", "personality difficulties"], "n/a (F60.x by type)",
 "Long-standing patterns in how a person thinks, feels, and relates to others that cause lasting distress or trouble.",
 "Everyone has a personality: habits of thinking, feeling, and relating. A personality disorder is diagnosed when those patterns are rigid, start by early adulthood, show up across many situations, and cause real distress or problems. The DSM groups ten types into three clusters. The labels are controversial: they've been used to dismiss people, especially those with trauma histories, and especially women. What's not controversial any more is that these difficulties are treatable, and people get better.",
 ["Being told I had a personality disorder felt like being told I was broken as a person. Then I found a therapist who explained it as patterns, not a verdict.", "The label got me turned away from services for years. The right team used it to get me the right therapy.", "I'm not my diagnosis. It describes some of my struggles. It doesn't describe me."],
 ["Rigid patterns of thinking, feeling, and relating that cause problems across life", "Starting in adolescence or early adulthood and lasting for years", "Distress for the person, or repeated trouble in relationships, work, or self-image", "Not explained by another condition, a substance, or a medical illness"],
 [{"myth": "A personality disorder means something is wrong with who you are.", "fact": "It describes patterns of coping that usually developed for understandable reasons, often in response to early adversity, and that can change."},
  {"myth": "Personality disorders can't be treated.", "fact": "Several therapies have strong evidence, especially for borderline personality disorder. Most people improve substantially over time."},
  {"myth": "People with personality disorders are manipulative or dangerous.", "fact": "This stigma causes real harm, including in healthcare. Most people with these diagnoses are struggling, not scheming, and are far more likely to be hurt than to hurt."}],
 {"plain": "About 1 in 10 adults meets criteria for some personality disorder in a given year, by US survey estimates. How the label is used varies a lot between countries.", "figure": "9.1% of US adults with any personality disorder in the past year (NCS-R)", "source_ref": "src-nimh-pd"},
 {"plain_summary": "Treatment is mainly psychological and longer-term. For borderline personality disorder, several structured therapies work well. For other types, evidence is thinner but therapy that builds self-understanding, emotional skills, and relationships helps. Medication isn't a treatment for personality disorder itself, though it may be used for depression, anxiety, or crisis symptoms, prescribed and monitored by a doctor. Consistent, respectful care relationships matter as much as the technique. Services that turn people away because of the label are going against guidelines.",
  "evidence_based_options": ["Structured psychological therapies, especially for borderline personality disorder (DBT, MBT, schema therapy, transference-focused therapy)", "Longer-term therapy focused on self-understanding, emotions, and relationships", "Treatment of co-occurring depression, anxiety, or substance use", "Crisis plans and consistent care relationships"],
  "self_help_that_supports_care": ["Reading about your diagnosis from sources written with people who have it", "Peer support with others who share the experience", "Learning emotional-regulation skills, even outside formal therapy", "Knowing your rights if a service tries to exclude you because of the label"],
  "guideline_refs": ["src-nice-cg78"]},
 "Do long-standing patterns in how you treat yourself and others keep causing pain, broken relationships, or crises? A full assessment can help. So can a therapist who works with personality difficulties. If you're in crisis or thinking about ending your life, use the crisis strip now.",
 "Having strong traits, being difficult sometimes, or going through a bad patch isn't a personality disorder. Trauma, autism, ADHD, and mood disorders can look similar. They are often wrongly labelled as personality disorders.",
 "People with these diagnoses recover. They build stable lives and relationships, and often become the wisest supporters of others.",
 ["borderline-personality-disorder", "antisocial-personality-disorder", "narcissistic-personality-disorder", "avoidant-personality-disorder", "obsessive-compulsive-personality-disorder", "alternative-model-for-personality-disorders", "posttraumatic-stress-disorder"],
 ["personality-trait", "stigma", "diagnosis", "formulation", "dbt", "mbt", "schema-therapy", "person-first-identity-first"],
 PD_COMMS, ("Soft line illustration of a person looking at a gallery wall of ten different framed portraits of themselves at different ages and moods, calm and curious, warm light. Pastel plum and cream.", "A person looks calmly at a wall of framed portraits of themselves at different ages and moods."),
 [DSM_P, NIMH_PD, NESARC, NICE78], qs=[PD_NOTE, "Replace placeholder related topic.", "Add verified PD-specific peer communities."],
 young="These disorders are rarely diagnosed before 18, because personality is still forming. Teens with intense emotional struggles can get early help without a label. That's usually the better route.",
 cult="What counts as 'odd' or 'excessive' depends on culture. The diagnosis is used far more in some countries than others, and clinicians are advised to consider cultural context before applying it.",
 subs=[{"title": "Cluster A: odd or eccentric", "text": "Paranoid, schizoid, and schizotypal personality disorders."}, {"title": "Cluster B: dramatic, emotional, or erratic", "text": "Antisocial, borderline, histrionic, and narcissistic personality disorders."}, {"title": "Cluster C: anxious or fearful", "text": "Avoidant, dependent, and obsessive-compulsive personality disorders."},
       {"title": "Personality change due to another medical condition; other specified and unspecified personality disorder", "icd10cm_code": "F07.0 / F60.89 / F60.9", "text": "Used when a brain injury or illness changes personality, or when difficulties don't fit one type."}],
 sens="elevated", notes=[PD_NOTE], clin=True, card_type="explainer"))

def pd(tid, name, title, aka, code, cluster, one, simple, feel, signs, myths, how, helps, reach, isnot, hope, related, gloss, comms, vis, srcs, qs=[], young=None, cult=None, sens="standard", notes=[], subs=None, lang_note=None):
    if not any(x.get('id') == 'src-nice-cg78' for x in srcs): srcs = srcs + [NICE78]
    return P(tid, name, title, aka, code, one, simple, feel, signs, myths, how, helps, reach, isnot, hope, related, gloss, comms, vis, srcs, qs=[PD_NOTE] + qs, young=young, cult=cult, sens=sens, notes=[PD_NOTE, f"Cluster {cluster}."] + notes, clin=True, subs=subs, lang_note=lang_note)

CARDS.append(pd("borderline-personality-disorder", "Borderline Personality Disorder", "Intense feelings, unstable relationships, shaky self", ["BPD", "emotionally unstable personality disorder (ICD-10 term)", "EUPD"], "F60.3", "B",
 "Intense, fast-changing emotions, fear of abandonment, unstable relationships, impulsive actions, and an unsure sense of self.",
 "Borderline personality disorder is a condition of emotional intensity. Feelings come fast, hit hard, and take a long time to settle. Relationships swing between closeness and conflict, driven by deep fear of abandonment. The sense of self can feel unstable or empty. Many people self-harm or feel suicidal when overwhelmed. It usually follows early trauma or invalidation, though not always. It carries heavy stigma, and it is one of the most treatable personality disorders, with several therapies that work.",
 ["My emotions are a radio with the volume stuck on full. Everyone else seems to have a dial.", "I'd push people away to test whether they'd stay. Then hate myself when they left.", "DBT gave me the dial. I still feel everything. I'm not drowning in it any more."],
 ["Intense emotions that shift quickly and are hard to settle", "Frantic efforts to avoid real or imagined abandonment", "Relationships that swing between idealizing and devaluing people", "An unstable or empty sense of self", "Impulsive actions when upset, or self-harm and suicidal feelings", "Intense anger, or feeling unreal or paranoid under stress"],
 [{"myth": "People with BPD are manipulative and attention-seeking.", "fact": "Behaviour that looks that way is usually a desperate attempt to manage unbearable feelings or fear of abandonment. This stigma keeps people from care."},
  {"myth": "BPD is untreatable and lifelong.", "fact": "Several therapies have strong evidence, and most people no longer meet criteria within ten years. Remission is the norm, not the exception."},
  {"myth": "BPD is just a label for difficult women.", "fact": "Men have BPD at similar rates but are diagnosed less often. The diagnosis has been misused, which is why careful assessment matters."}],
 {"plain": "About 1 or 2 in 100 adults have borderline personality disorder in a given year, with higher rates among people in mental health services.", "figure": "1.4% past-year prevalence among US adults (NCS-R)", "source_ref": "src-nimh-pd"},
 {"plain_summary": "Structured psychological therapy is the treatment: dialectical behaviour therapy (DBT), mentalization-based treatment (MBT), schema therapy, and transference-focused therapy all have evidence. They teach skills for managing emotions and relationships and work on the patterns underneath. Medication is not a treatment for BPD itself, though it may be used short-term or for co-occurring conditions, prescribed and monitored by a doctor. A crisis plan, continuity of care, and being treated with respect are essential.",
  "evidence_based_options": ["Dialectical behaviour therapy (DBT), usually a year or more with group and individual sessions", "Mentalization-based treatment (MBT) or schema therapy", "A written crisis plan and consistent care team", "Treatment for co-occurring depression, PTSD, or substance use"],
  "self_help_that_supports_care": ["DBT skills workbooks and apps, ideally alongside therapy", "Naming the emotion and its intensity out of ten before acting", "Delaying impulsive actions by a set time", "Peer support from others with BPD, where shame drops away"],
  "guideline_refs": ["src-nice-cg78"]},
 "If intense emotions, unstable relationships, and fear of abandonment keep leading to crises or self-harm, ask a doctor or mental health service for an assessment and for therapy designed for BPD. If you're having thoughts of ending your life, use the crisis strip now.",
 "Strong emotions in your teens, mood swings in a stressful time, or being hurt by a breakup aren't BPD. Bipolar disorder involves mood episodes lasting days to weeks, not hours. Complex PTSD and ADHD overlap with BPD and are often confused with it.",
 "Most people with BPD get much better, and many say the sensitivity that once hurt them became their greatest strength in relationships and work.",
 ["about-personality-disorders", "posttraumatic-stress-disorder", "nonsuicidal-self-injury", "major-depressive-disorder", "bipolar-ii-disorder", "adhd", "child-abuse-and-neglect"],
 ["emotional-dysregulation", "splitting", "identity-disturbance", "dbt", "mbt", "schema-therapy", "crisis-plan", "manipulative-label", "stigma"],
 ["nea-bpd-family-connections", "mind-side-by-side", "sane-forums-australia"],
 ("Soft line illustration of a person on a jetty at sunset with a friend, feet in the water, a notebook of DBT skills open between them, calm lake. Pastel plum and amber.", "Two people sit on a jetty at sunset with their feet in the water and a notebook open between them."),
 [DSM_P, NIMH_PD, NICE78, src("src-neabpd", "National Education Alliance for Borderline Personality Disorder: Family Connections", "NEA-BPD", "https://www.borderlinepersonalitydisorder.org/family-connections/", seen=True, note="Brochure URL seen; programme page from memory.")],
 qs=["Add a verified peer community for people with BPD (r/BPD, Emotions Matter) once rules are read."],
 young="BPD can be diagnosed in adolescence when the pattern is clear and lasting, and early DBT-based treatment works well. Many clinicians prefer to treat the difficulties without the label in teens.",
 cult="Diagnosis rates vary widely by country and are higher among women, people in poverty, and people with trauma histories. Some cultures express emotional pain through the body or through family conflict rather than self-harm.",
 sens="elevated", notes=["Self-harm and suicide risk; crisis strip required; no methods."]))

CARDS.append(pd("antisocial-personality-disorder", "Antisocial Personality Disorder", "A pattern of disregarding other people's rights", ["ASPD", "dissocial personality disorder (ICD term)", "psychopathy and sociopathy (popular, non-DSM terms)"], "F60.2", "B",
 "A long-standing pattern, from adolescence, of breaking rules and others' rights, deceit, impulsivity, aggression, and lack of remorse.",
 "Antisocial personality disorder is a lasting pattern, starting with conduct problems before 15, of ignoring laws and others' rights: lying, impulsive and reckless behaviour, aggression, irresponsibility, and little remorse. It is strongly linked to childhood adversity and conduct disorder. 'Psychopath' and 'sociopath' are popular labels, not diagnoses, and most people with ASPD aren't the movie villain; many struggle with substance use, unemployment, and early death. Treatment is harder than for other conditions, but not hopeless, especially when it starts young.",
 ["I grew up in chaos and learned that rules were for other people. Prison was the first structure I'd ever had.", "Therapy didn't make me feel guilt. It made me see the cost of what I was doing to my own life.", "My brother has this diagnosis. He's not a monster. He's a damaged person who hurts people and himself."],
 ["Repeatedly breaking laws or social rules since the teens", "Lying, conning, or using others for gain", "Impulsive, reckless, or aggressive behaviour", "Irresponsibility with work, money, or commitments", "Little remorse after hurting others", "Conduct problems before age 15"],
 [{"myth": "Everyone with ASPD is a dangerous psychopath.", "fact": "ASPD covers a wide range. A minority show the cold, calculating pattern popular culture focuses on; most are impulsive, chaotic, and self-destructive."},
  {"myth": "It's untreatable, so why bother.", "fact": "Treatment is challenging, but programmes that build skills, reduce substance use, and address conduct problems early show real results. Prevention in childhood works best."},
  {"myth": "People with ASPD are born that way.", "fact": "Genetics play a part, but childhood abuse, neglect, and chaotic environments are major drivers. It's made as much as born."}],
 {"plain": "Around 3 to 4 in 100 US adults meet criteria at some point, men far more than women, with much higher rates in prisons.", "figure": "3.6% lifetime prevalence among US adults (NESARC 2001–02); about 1% of women and 3% of men in general-population estimates", "source_ref": "src-nesarc-pd"},
 {"plain_summary": "Guidelines recommend group-based cognitive and behavioural programmes that target impulsivity, problem-solving, and offending, and treatment of substance use and other conditions. Medication isn't a treatment for ASPD, though it may be used for co-occurring conditions, prescribed and monitored by a doctor. The strongest results come from preventing it: early support for children with conduct problems and their families. Services that are consistent and firm but respectful work better than punitive ones.",
  "evidence_based_options": ["Group cognitive-behavioural programmes targeting impulsivity and offending", "Treatment of substance use and co-occurring conditions", "Early intervention for children and teens with conduct disorder, including parent training", "Multisystemic therapy and similar family-based programmes for young people"],
  "self_help_that_supports_care": ["Structure and routine, which many people with ASPD find helps", "Recognizing the personal cost of impulsive actions and planning before acting", "Staying away from substances, which fuel the worst outcomes", "Support for family members, who often carry a heavy load"],
  "guideline_refs": ["src-nice-cg77"]},
 "If a pattern of rule-breaking, aggression, and impulsivity is wrecking your life or relationships, a mental health or forensic service can help, and treating substance use is a good first step. If you're a family member, support exists for you too.",
 "Occasional rule-breaking, rebellion in the teens, or crimes driven by poverty or addiction don't by themselves mean ASPD. Conduct disorder in under-18s is the childhood pattern; not all children with it develop ASPD.",
 "Many people with antisocial patterns settle with age and structure. Early support for children at risk changes life courses.",
 ["about-personality-disorders", "conduct-disorder", "substance-use-disorders-overview", "adhd", "narcissistic-personality-disorder", "crime-disaster-and-legal-problems"],
 ["impulsivity", "adverse-childhood-experiences", "stigma", "stigma-words"],
 PD_COMMS, ("Soft line illustration of a person planting a tree in a community garden with a group, gloves on, a mentor beside them, a calm sunny day. Pastel plum and green. No prison imagery.", "A person plants a tree in a community garden with a mentor beside them."),
 [DSM_P, NESARC, NICE77],
 qs=["No ASPD-specific community found; most support exists for family members. Verify family-of-ASPD resources."],
 young="ASPD can't be diagnosed before 18. The childhood precursor is conduct disorder, and 'callous-unemotional traits' mark a higher-risk group. Early, family-based help is the best prevention.",
 cult="Behaviour that breaks laws reflects circumstances as well as personality: poverty, discrimination, and community violence all raise rates. Clinicians are warned not to apply the label to behaviour that is adaptive in a dangerous environment.",
 sens="elevated", notes=["High stigma; wording avoids 'psychopath' and 'sociopath' as labels."]))

CARDS.append(pd("narcissistic-personality-disorder", "Narcissistic Personality Disorder", "Needing admiration, and struggling without it", ["NPD"], "F60.81", "B",
 "A pattern of feeling special, needing to be admired, and struggling to feel for others, usually covering fragile self-worth.",
 "Narcissistic personality disorder is a lasting pattern of feeling special and entitled, needing admiration, and finding it hard to recognize other people's feelings. Underneath there's often fragile, easily wounded self-esteem, with shame and rage when criticized. It causes real problems in relationships and work, and real suffering, especially when life brings failure or ageing. The word 'narcissist' is thrown around online at anyone selfish; the diagnosis is specific and uncommon. Treatment is possible, and people do change.",
 ["I needed to be the best in every room. When I wasn't, I fell apart, and I took it out on the people closest to me.", "Therapy started when my marriage ended. It took a long time to admit the problem wasn't everyone else.", "People online use 'narcissist' as a curse word. For me it was a diagnosis that finally explained the emptiness."],
 ["An inflated sense of importance, achievements, or specialness", "Needing constant admiration; being preoccupied with success or status", "Feeling entitled, exploiting others, or envying them", "Finding it hard to notice or care about others' feelings", "Reacting to criticism with rage, contempt, or collapse", "Underneath: fragile self-worth, shame, and emptiness"],
 [{"myth": "Narcissists love themselves.", "fact": "Most people with NPD have fragile self-worth and deep shame, which grandiosity defends against. It's closer to self-doubt than self-love."},
  {"myth": "Anyone selfish or difficult is a narcissist.", "fact": "NPD is a specific, uncommon diagnosis. Armchair-diagnosing an ex or a boss rarely helps anyone and adds stigma to people with the condition."},
  {"myth": "People with NPD never change.", "fact": "Change is slow and usually starts with a crisis, but longer-term therapy helps many people develop empathy and steadier self-worth."}],
 {"plain": "Estimates vary widely, from under 1 in 100 to around 6 in 100 adults, depending on the study. Men are diagnosed more often.", "figure": "DSM-5-TR text: 0%–6.2% across community samples; NESARC excluded NPD from its first wave", "source_ref": "src-dsm", "note": "Needs a primary citation."},
 {"plain_summary": "Longer-term talk therapy is the main treatment. Approaches such as schema therapy, mentalization-based therapy, and psychodynamic therapy work on self-worth, empathy, and relationships. Treatment often starts after a loss, a breakdown, or depression, and treating those is part of it. Medication isn't a treatment for NPD itself. It may be used for depression or anxiety, prescribed and monitored by a doctor. Therapy works best when it is steady, honest, and never humiliating.",
  "evidence_based_options": ["Longer-term psychotherapy: schema, mentalization-based, transference-focused, or psychodynamic", "Treatment of co-occurring depression, anxiety, or substance use", "Couples or family work where relationships are strained", "Medication for co-occurring conditions only, prescribed and monitored by a doctor"],
  "self_help_that_supports_care": ["Noticing the shame underneath anger at criticism", "Practising curiosity about other people's inner lives", "Staying in therapy past the point where it gets uncomfortable", "For family: support for yourself, and clear boundaries"],
  "guideline_refs": ["src-nice-cg78"]},
 "Does needing to be admired, or struggling to care about others, keep costing you relationships or work? Does criticism send you into rage or despair? A therapist who works with personality difficulties can help. A moment of crisis, when you most want change, is a good time to start.",
 "Confidence, ambition, or vanity aren't NPD. Everyone is self-centred sometimes. The diagnosis needs a lasting pattern that causes significant impairment or distress.",
 "People who stick with therapy describe something they never expected: relationships that feel real.",
 ["about-personality-disorders", "antisocial-personality-disorder", "histrionic-personality-disorder", "borderline-personality-disorder", "major-depressive-disorder"],
 ["grandiosity", "narcissist-pop", "splitting", "schema-therapy", "psychodynamic-therapy", "stigma"],
 PD_COMMS, ("Soft line illustration of a person sitting across from a therapist, both leaning in, a window with a view of a quiet street, a mirror on the wall turned slightly away. Pastel plum and grey.", "A person and a therapist sit leaning toward each other beside a window, a mirror turned slightly away."),
 [DSM_P, NIMH_PD],
 qs=["Find a primary prevalence source.", "Only general PD communities listed; look for NPD-specific peer support (for example r/NPD) and verify."],
 cult="Some cultures reward selling yourself. Traits that look narcissistic elsewhere may be normal there. Clinicians weigh this before diagnosing.",
 sens="standard", notes=["The 'narcissist' label is widely misused online; the card addresses this directly."]))

CARDS.append(pd("histrionic-personality-disorder", "Histrionic Personality Disorder", "Needing to be the centre of attention", ["HPD"], "F60.4", "B",
 "Seeking attention and approval through dramatic emotion, appearance, or charm, with feelings that are intense but shift quickly.",
 "Histrionic personality disorder is a lasting pattern where a person feels uncomfortable unless they're the centre of attention, and uses dramatic emotion, flirtation, appearance, or charm to get it. Feelings are expressed strongly but can seem shallow and change fast, and relationships feel closer than they really are. Underneath there's often a fear of being unnoticed or unloved. It's diagnosed less now than it once was, and it's treatable with therapy that builds a steadier sense of worth.",
 ["If I wasn't performing, I felt invisible. And invisible felt like dying.", "People called me dramatic. I just didn't know how to be seen any other way.", "Therapy helped me find out who I was when nobody was watching."],
 ["Discomfort when not the centre of attention", "Dramatic, rapidly shifting, or exaggerated emotions", "Using appearance, charm, or flirtation to draw attention", "Speech that's impressionistic and short on detail", "Feeling relationships are closer than they are; easily influenced by others"],
 [{"myth": "It's just being dramatic or 'extra'.", "fact": "Being expressive is a personality style. HPD is a lasting pattern driven by distress and causing real problems in relationships."},
  {"myth": "It only affects women.", "fact": "It's diagnosed more in women, partly because of bias in how 'dramatic' behaviour is read. Men have it too."},
  {"myth": "People with HPD are shallow.", "fact": "The intensity is real; what's hard is sustaining feelings and connection, often because of a deep fear of being unnoticed."}],
 {"plain": "Around 1 to 2 in 100 adults meet criteria, by US survey estimates.", "figure": "About 1.8% of US adults (NESARC 2001–02, roughly 3.8 million)", "source_ref": "src-nesarc-pd"},
 {"plain_summary": "Psychotherapy is the treatment, usually longer-term: psychodynamic, schema, or cognitive approaches that help the person notice the fear beneath the performance, build a steadier self-worth, and form relationships that don't depend on constant attention. Medication isn't a treatment for HPD itself; co-occurring depression or anxiety may be treated, prescribed and monitored by a doctor.",
  "evidence_based_options": ["Psychodynamic, schema, or cognitive therapy", "Group therapy, with care", "Treatment of co-occurring depression or anxiety", "Couples therapy where relationships are strained"],
  "self_help_that_supports_care": ["Noticing what you feel when attention moves elsewhere, and sitting with it", "Practising listening in conversations", "Journalling to find the detail behind big feelings", "Peer support with people who value you quietly"],
  "guideline_refs": ["src-nice-cg78"]},
 "If a need for attention and intense, shifting emotions keep damaging relationships or leaving you feeling empty, a therapist experienced with personality difficulties can help.",
 "Being outgoing, expressive, or flamboyant isn't a disorder. Many cultures and professions reward exactly these traits.",
 "People with histrionic patterns learn that they can be seen and loved without a performance.",
 ["about-personality-disorders", "narcissistic-personality-disorder", "borderline-personality-disorder", "dependent-personality-disorder"],
 ["emotional-lability", "psychodynamic-therapy", "schema-therapy", "attachment"],
 PD_COMMS, ("Soft line illustration of a person sitting quietly in a park sketching, a friend reading nearby, both content, no audience. Pastel plum and sage.", "A person sketches quietly in a park while a friend reads nearby."),
 [DSM_P, NESARC], cult="Expressiveness that's normal in one culture can look 'histrionic' in another. Diagnosis requires impairment, not just style."))

CARDS.append(pd("paranoid-personality-disorder", "Paranoid Personality Disorder", "Living with constant suspicion of others", ["PPD"], "F60.0", "A",
 "A lasting pattern of distrusting and suspecting others, reading hidden threats into ordinary events, without the fixed delusions of psychosis.",
 "Paranoid personality disorder is a long-standing way of seeing the world as hostile. The person assumes others are out to exploit, deceive, or harm them, reads insults into innocent remarks, holds grudges, and finds it hard to confide in anyone. Unlike psychosis, these are suspicions rather than fixed false beliefs. It often follows childhood experiences where trust was betrayed. It's lonely and exhausting, and therapy that builds trust slowly can help.",
 ["I assume everyone has an angle. It's kept me safe. It's also kept me alone.", "A colleague forgot to say good morning and I spent the week sure she was plotting against me.", "It took a year to trust my therapist. That year was the treatment."],
 ["Expecting others to exploit, deceive, or harm you, without good reason", "Doubting the loyalty of friends and partners", "Reading hidden insults or threats into harmless remarks", "Holding grudges; reacting angrily to perceived attacks", "Reluctance to confide, fearing information will be used against you"],
 [{"myth": "Paranoid personality disorder is the same as paranoid schizophrenia.", "fact": "PPD involves suspicion and mistrust, not delusions or hallucinations. People with PPD are in touch with reality."},
  {"myth": "People with PPD are dangerous.", "fact": "Most are withdrawn and guarded rather than aggressive. The main harm is to their own relationships and wellbeing."},
  {"myth": "You can reason someone out of it.", "fact": "Arguing confirms their fear of being attacked. Patient, consistent honesty builds trust slowly; that's the work of therapy."}],
 {"plain": "Around 2 to 4 in 100 adults meet criteria, by US survey estimates, though many never seek help.", "figure": "About 4.4% of US adults (NESARC 2001–02); other estimates 2.3%–4.4%", "source_ref": "src-nesarc-pd"},
 {"plain_summary": "Psychotherapy is the main treatment, and the therapeutic relationship itself is the medicine: a consistent, honest, non-defensive therapist over time. Cognitive approaches help test suspicious interpretations against evidence. Medication isn't a treatment for PPD, though anxiety or depression may be treated, prescribed and monitored by a doctor. Progress is slow and real.",
  "evidence_based_options": ["Individual psychotherapy with a steady, transparent therapist", "Cognitive therapy to examine suspicious interpretations", "Treatment of co-occurring anxiety or depression", "Avoiding group formats early, which can feel threatening"],
  "self_help_that_supports_care": ["Testing one suspicion at a time against what actually happens", "Noticing the difference between 'I feel threatened' and 'I am threatened'", "Choosing one person to confide a small thing in", "Being honest with the therapist about doubting them; that's part of it"],
  "guideline_refs": ["src-nice-cg78"]},
 "If constant suspicion is costing you relationships, work, or peace, and you can bear the idea, a therapist experienced with personality difficulties can help. You can start by saying you don't trust them yet.",
 "Reasonable wariness after real betrayal or in a genuinely hostile environment isn't a disorder. Paranoid delusions, where beliefs are fixed and detached from reality, point to a psychotic disorder.",
 "People with paranoid patterns can learn, slowly, that some people are safe. Every trusted relationship makes the next one easier.",
 ["about-personality-disorders", "schizotypal-personality-disorder", "delusional-disorder", "posttraumatic-stress-disorder", "schizoid-personality-disorder"],
 ["paranoia", "cognitive-distortion", "trauma", "psychodynamic-therapy"],
 PD_COMMS, ("Soft line illustration of a person sitting at a chess table in a park with an older neighbour, mid-game, both relaxed, a thermos between them. Pastel plum and sand.", "A person plays chess in a park with a neighbour, a thermos between them."),
 [DSM_P, NESARC], cult="Members of groups that face real discrimination or surveillance may be wary for good reason. Clinicians are advised to weigh this before diagnosing.",
 sens="standard"))

CARDS.append(pd("schizoid-personality-disorder", "Schizoid Personality Disorder", "Preferring to be alone, with little pull to others", ["SzPD"], "F60.1", "A",
 "A lasting pattern of detachment from relationships and a narrow range of expressed emotion, with little wish for closeness.",
 "Schizoid personality disorder describes people who consistently prefer solitude, have little desire for close relationships, including sexual ones, take pleasure in few activities, and seem emotionally cool or distant to others. They're not lonely in the usual sense, not anxious about people, and in touch with reality. It's one of the least understood types, and many people with it live quietly and ask nothing of services. It becomes a concern when it causes distress or blocks things the person wants.",
 ["I don't dislike people. I just don't need them the way everyone assumes I should.", "Family thought I was depressed. I wasn't. I was fine alone, and they couldn't accept that.", "Therapy wasn't about making me social. It was about finding what I actually want from life."],
 ["Not wanting or enjoying close relationships, including family", "Almost always choosing solitary activities", "Little interest in sex with another person", "Taking pleasure in few, if any, activities", "Appearing indifferent to praise or criticism; emotionally flat or detached"],
 [{"myth": "Schizoid means schizophrenia.", "fact": "Schizoid personality disorder has no psychosis. The word shares a root but the conditions are different."},
  {"myth": "People with schizoid traits are secretly lonely and need pushing into social life.", "fact": "Many are genuinely content alone. Pressure to socialize usually causes distress rather than helping."},
  {"myth": "It's the same as being an introvert or autistic.", "fact": "Introverts enjoy some closeness. Autism involves communication and sensory differences from childhood. Schizoid patterns are about not desiring connection; the three can be confused."}],
 {"plain": "Around 3 in 100 adults meet criteria, by US survey estimates, though few seek help.", "figure": "About 3.1% of US adults (NESARC 2001–02, roughly 6.5 million)", "source_ref": "src-nesarc-pd"},
 {"plain_summary": "Treatment is only needed if the person wants something to change. When it is, individual therapy that respects their need for distance and explores what they value works best; group therapy may help some people practise connection at their own pace. Depression or anxiety, if present, is treated, with any medication prescribed and monitored by a doctor.",
  "evidence_based_options": ["Individual psychotherapy at the person's own pace", "Cognitive or psychodynamic approaches focused on the person's goals", "Group therapy in some cases", "Treatment of co-occurring depression"],
  "self_help_that_supports_care": ["Deciding for yourself what kind of connection, if any, you want", "Choosing work and living arrangements that suit you", "One low-demand regular contact, if that appeals", "Noticing if solitude has tipped into depression"],
  "guideline_refs": ["src-nice-cg78"]},
 "If detachment is causing you distress, or blocking something you want, like a job or a relationship, a therapist who won't push can help. If low mood or hopelessness creep in, reach out.",
 "Introversion, preferring a quiet life, or choosing solitude after a hard time isn't a disorder. Autism and schizotypal personality disorder are different and are sometimes confused with it.",
 "People with schizoid patterns build lives that fit them, and some find connection on their own terms.",
 ["about-personality-disorders", "schizotypal-personality-disorder", "avoidant-personality-disorder", "autism-spectrum-disorder", "major-depressive-disorder"],
 ["affect", "social-battery", "psychodynamic-therapy"],
 PD_COMMS, ("Soft line illustration of a person contentedly tending a rooftop vegetable garden alone at dawn, city soft in the background, a cat on the wall. Pastel plum and green.", "A person tends a rooftop vegetable garden alone at dawn, a cat on the wall."),
 [DSM_P, NESARC], qs=["Look for r/Schizoid and verify."], sens="standard"))

CARDS.append(pd("schizotypal-personality-disorder", "Schizotypal Personality Disorder", "Unusual beliefs and discomfort with closeness", ["STPD"], "F21", "A",
 "A lasting pattern of unusual beliefs, odd ways of seeing things, eccentric speech or dress, and deep unease with closeness.",
 "Schizotypal personality disorder sits between personality and psychosis. People have unusual beliefs, such as mind-reading or special signs beyond what their culture holds. They may sense a presence, speak or dress in odd ways, and be suspicious. Social anxiety is intense and doesn't ease with time. Unlike schizophrenia, there are no lasting delusions or hallucinations, though a minority later develop psychosis. It appears in both the personality and the psychotic chapters. Therapy and sometimes medication help.",
 ["I've always known things before they happen. People think I'm strange. Maybe I am.", "Crowds feel like static. I can't make friends past a certain point; the wall goes up.", "A psychiatrist who treated my ideas with respect, not alarm, was the first I could talk to."],
 ["Unusual beliefs or magical thinking beyond cultural norms", "Odd perceptions, like sensing presences or seeing meaning in coincidences", "Odd thinking, speech, or appearance", "Being suspicious or feeling others are against you", "Intense social anxiety that doesn't fade with familiarity; few close friends", "Showing little emotion, or emotion that doesn't fit the moment"],
 [{"myth": "Schizotypal is mild schizophrenia.", "fact": "It's a personality pattern without sustained psychosis. Most people with it never develop schizophrenia, though the risk is higher than average."},
  {"myth": "Unusual beliefs mean someone is mentally ill.", "fact": "Spiritual, religious, and cultural beliefs are not symptoms. The diagnosis needs beliefs that go beyond the person's culture and cause distress or impairment."},
  {"myth": "People with STPD are just eccentric.", "fact": "Eccentricity is fine. STPD involves real suffering, usually from isolation and anxiety, and it deserves care."}],
 {"plain": "Around 1 to 4 in 100 adults meet criteria, by US survey estimates.", "figure": "About 3.9% of US adults (NESARC wave 2); other estimates around 1%", "source_ref": "src-dsm", "note": "NESARC wave-2 figure from memory; needs confirmation."},
 {"plain_summary": "Talk therapy is the main treatment. It builds social skills and gently tests unusual beliefs, using CBT and supportive approaches. A low dose of antipsychotic medication, prescribed and monitored by a doctor, sometimes helps with odd perceptions and thinking. Treating social anxiety and depression matters. Because the risk of psychosis is raised, staying in touch with services helps catch any change early.",
  "evidence_based_options": ["CBT and social-skills training", "Supportive psychotherapy", "Low-dose antipsychotic medication in some cases, prescribed and monitored by a doctor", "Treatment of social anxiety and depression; monitoring for psychosis"],
  "self_help_that_supports_care": ["One or two safe relationships, built slowly", "Grounding techniques when perceptions feel unsettling", "Writing down unusual experiences to discuss rather than act on", "Peer support with people who respect unusual experiences"],
  "guideline_refs": ["src-nice-cg178"]},
 "If unusual experiences, suspicion, and social anxiety are isolating you or causing distress, an assessment can help. Reach out quickly if beliefs become fixed and certain, or if you start hearing voices.",
 "Spiritual, religious, or cultural beliefs that your community shares aren't symptoms. Schizophrenia involves lasting delusions and hallucinations. Autism and social anxiety can look similar and are sometimes confused with it.",
 "With support, people with schizotypal patterns find places where being unusual is welcome. Most never develop psychosis.",
 ["about-personality-disorders", "schizophrenia", "paranoid-personality-disorder", "schizoid-personality-disorder", "social-anxiety-disorder", "attenuated-psychosis-syndrome"],
 ["ideas-of-reference", "paranoia", "grounding", "prodrome", "antipsychotic"],
 PD_COMMS + ["hearing-voices-network-groups"], ("Soft line illustration of a person at a small astronomy club meeting outdoors, telescopes pointing at a starry sky, one other person showing them a star chart. Pastel plum and indigo.", "A person at an outdoor astronomy club meeting looks at a star chart with another member under a starry sky."),
 [DSM_P, NESARC, src("src-nice-cg178", "Psychosis and schizophrenia in adults: prevention and management (CG178)", "NICE", "https://www.nice.org.uk/guidance/cg178", 2014, seen=True)],
 qs=["Confirm prevalence citation."], cult="Beliefs in spirits, omens, or healing that are normal in a community are not symptoms. Assessment must ask what the person's culture considers ordinary.", sens="elevated", notes=["Raised risk of psychosis; crisis strip required."]))

CARDS.append(pd("avoidant-personality-disorder", "Avoidant Personality Disorder", "Wanting closeness, too afraid of rejection to risk it", ["AvPD", "anxious personality disorder (ICD-10 term)"], "F60.6", "C",
 "Avoiding people and situations out of intense fear of criticism and rejection, and feeling inadequate, despite wanting connection.",
 "Avoidant personality disorder is a deep, long-standing fear of being judged and found wanting. People with it long for closeness but avoid relationships, work, and social situations unless they're sure of being liked, see themselves as inferior and unappealing, and read criticism into neutral reactions. It overlaps heavily with social anxiety disorder and is often seen as its more pervasive form. It usually starts in childhood or the teens and is treatable with the same therapies, over a longer run.",
 ["I want friends more than anything. I also can't bear the thought of being seen.", "I turned down two promotions because they involved meeting people. I told myself I didn't want them.", "Schema therapy got at the 'I'm defective' belief I'd had since I was eight. Things changed after that."],
 ["Avoiding work or activities that involve a lot of contact with people", "Unwilling to get involved with people unless sure of being liked", "Holding back in relationships for fear of shame or ridicule", "Preoccupied with being criticized or rejected", "Seeing yourself as socially inept, unappealing, or inferior", "Very reluctant to try new things in case they're embarrassing"],
 [{"myth": "It's just shyness.", "fact": "Shyness is a trait. AvPD causes pervasive avoidance and a damaged self-image that limits a whole life."},
  {"myth": "People with AvPD don't want relationships.", "fact": "They want them badly. The fear of rejection, not lack of desire, keeps them away. That's the difference from schizoid patterns."},
  {"myth": "Exposure will fix it quickly.", "fact": "Social anxiety treatments help, but AvPD usually needs longer work on the core belief of being defective, often with schema or psychodynamic therapy."}],
 {"plain": "Around 2 in 100 adults meet criteria, by US survey estimates, with similar rates in men and women.", "figure": "About 2.4% of US adults (NESARC 2001–02, roughly 4.9 million)", "source_ref": "src-nesarc-pd"},
 {"plain_summary": "Treatment combines what works for social anxiety, CBT with graded exposure and social-skills work, with longer-term therapy on the beliefs underneath, such as schema therapy or psychodynamic approaches. Group therapy, once tolerable, can be powerful. Antidepressants, prescribed and monitored by a doctor, may help the anxiety and depression that often accompany it. Progress is gradual and tends to last.",
  "evidence_based_options": ["CBT with graded exposure and social-skills training", "Schema therapy or psychodynamic therapy for the core beliefs", "Group therapy at the right stage", "SSRI antidepressants for co-occurring anxiety or depression, prescribed and monitored by a doctor"],
  "self_help_that_supports_care": ["Small social experiments with a planned exit, repeated", "Writing down the evidence against 'I'm inferior'", "Online peer communities as a lower-risk starting point", "Celebrating attempts, not just outcomes"],
  "guideline_refs": ["src-nice-cg159"]},
 "If fear of rejection has shaped most of your choices for years, and loneliness or missed chances are the price, a therapist experienced with social anxiety and personality difficulties can help. Online or written first contact is a fine way to start.",
 "Shyness, introversion, or avoiding one specific situation isn't AvPD. Social anxiety disorder is similar but narrower. Schizoid personality disorder involves not wanting closeness, which is the opposite.",
 "People with avoidant patterns, treated with patience, go on to friendships, partnerships, and work they never thought they could have.",
 ["about-personality-disorders", "social-anxiety-disorder", "dependent-personality-disorder", "schizoid-personality-disorder", "major-depressive-disorder"],
 ["shyness-vs-social-anxiety", "inner-critic", "avoidance", "exposure-therapy", "schema-therapy", "rejection-sensitivity"],
 ["reddit-r-avoidant"] + PD_COMMS, ("Soft line illustration of a person at the doorway of a community class, one foot inside, the instructor smiling and holding the door, warm light. Pastel plum and yellow.", "A person stands at the doorway of a community class with one foot inside as the instructor holds the door and smiles."),
 [DSM_P, NESARC, src("src-nice-cg159", "Social anxiety disorder: recognition, assessment and treatment (CG159)", "NICE", "https://www.nice.org.uk/guidance/cg159", 2013, seen=True)],
 young="Avoidant patterns usually begin in childhood with extreme shyness and fear of new people, and worsen in adolescence. Early treatment of social anxiety can prevent the pattern setting."))

CARDS.append(pd("dependent-personality-disorder", "Dependent Personality Disorder", "Needing others to decide, fearing coping alone", ["DPD"], "F60.7", "C",
 "Needing to be looked after, going along with others, a deep fear of being left, and trouble deciding alone.",
 "Dependent personality disorder is a long-standing pattern of feeling unable to cope alone. People with it struggle to make everyday decisions without lots of advice, let others take responsibility for major areas of their life, find it hard to disagree for fear of losing support, go to great lengths to get care, and feel helpless when alone. When a relationship ends they urgently seek another. It often follows a childhood where independence was discouraged or unsafe, and it is treatable.",
 ["I couldn't order at a restaurant without checking what my husband thought. When he left, I didn't know who I was.", "I stayed in a bad relationship for a decade because being alone felt impossible.", "Therapy was the first place I made a decision and nobody told me I'd got it wrong."],
 ["Trouble making everyday decisions without lots of advice and reassurance", "Needing others to take responsibility for major areas of life", "Hard to disagree with others for fear of losing their support", "Feeling helpless or uncomfortable alone", "Urgently seeking a new relationship when one ends", "Going to great lengths to get care and support"],
 [{"myth": "Dependent people are just weak or lazy.", "fact": "The pattern is driven by fear and a learned belief in one's own incompetence, often from early experiences. It's painful, not comfortable."},
  {"myth": "It's only a problem for women.", "fact": "It's diagnosed more in women, but men have it too, and gender roles shape how it's noticed."},
  {"myth": "Leaving the relationship fixes it.", "fact": "Without therapy, the pattern repeats in the next relationship. The work is on the belief about coping alone."}],
 {"plain": "Dependent personality disorder is uncommon. It affects well under 1 in 100 adults, by US survey estimates.", "figure": "About 0.5% of US adults (NESARC 2001–02, roughly 1 million)", "source_ref": "src-nesarc-pd"},
 {"plain_summary": "Talk therapy is the treatment. CBT and schema approaches build confidence in deciding things, speaking up, and being alone. Psychodynamic work looks at where the pattern came from. Therapists take care not to become the new person the client leans on. Anxiety or depression alongside it may be treated with medication, prescribed and monitored by a doctor. Progress comes from practising independence in small steps.",
  "evidence_based_options": ["CBT and assertiveness training", "Schema therapy or psychodynamic therapy", "Graded practice of independent decisions", "Treatment of co-occurring anxiety or depression"],
  "self_help_that_supports_care": ["Making one small decision a day without asking anyone", "Spending planned short periods alone and noticing you cope", "Saying a small 'no' or 'I disagree' and surviving it", "Support groups for people leaving controlling relationships, where relevant"],
  "guideline_refs": ["src-nice-cg78"]},
 "If you can't make decisions or be alone without intense anxiety, or you've stayed in harmful relationships because leaving felt impossible, a therapist can help. If you're in an abusive relationship, domestic abuse services can help you plan safely.",
 "Depending on others during illness, disability, or crisis is normal. Cultures that value interdependence aren't disordered. The diagnosis needs fear and submission that cause harm across life.",
 "People with dependent patterns discover, decision by decision, that they can run their own lives, and often that they're good at it.",
 ["about-personality-disorders", "avoidant-personality-disorder", "borderline-personality-disorder", "separation-anxiety-disorder", "partner-violence-and-adult-abuse"],
 ["people-pleasing", "codependency", "attachment", "boundaries", "schema-therapy"],
 PD_COMMS, ("Soft line illustration of a person studying a train timetable alone at a station, ticket in hand, a small confident smile, morning light. Pastel plum and sky blue.", "A person studies a train timetable alone at a station, ticket in hand, with a small confident smile."),
 [DSM_P, NESARC], cult="In cultures where decisions are made by family and interdependence is valued, deference isn't a disorder. The diagnosis applies only when the pattern causes distress or harm within the person's own context.",
 sens="elevated", notes=["Links to domestic abuse resources because of vulnerability to controlling relationships."]))

CARDS.append(pd("obsessive-compulsive-personality-disorder", "Obsessive-Compulsive Personality Disorder", "When rules, order, and control take over", ["OCPD", "anankastic personality disorder (ICD-10 term)"], "F60.5", "C",
 "Perfectionism, rigid rules, and control, with order and work prized over flexibility, enjoyment, and relationships.",
 "Obsessive-compulsive personality disorder is not OCD. It's a long-standing way of being: perfectionism so strict that tasks don't get finished, preoccupation with rules, lists, and order, devotion to work over relationships and fun, rigidity about morals, inability to delegate, hoarding money or worn-out objects, and stubbornness. People with OCPD often see these as virtues and are brought to treatment by exhausted partners or burnout. It's the most common personality disorder, and therapy helps.",
 ["My way is the right way. I can prove it. I also can't understand why everyone has left.", "I spent so long perfecting the report that I missed the deadline. Again.", "Therapy taught me 'good enough' wasn't a moral failure. My marriage survived because of that."],
 ["Perfectionism that interferes with finishing tasks", "Preoccupation with rules, lists, order, and schedules", "Devotion to work and productivity, excluding leisure and friendships", "Rigid, inflexible about morals, ethics, or values", "Unable to delegate unless others do things exactly their way", "Stubbornness; miserly spending; keeping worn-out objects"],
 [{"myth": "OCPD is the same as OCD.", "fact": "OCD involves unwanted intrusive thoughts and anxiety-driven rituals the person hates. OCPD is a personality style of control and perfectionism the person often values. They need different treatments."},
  {"myth": "Being organized and hardworking is a disorder now?", "fact": "No. OCPD is when rigidity and perfectionism cause real harm: missed deadlines, broken relationships, no joy."},
  {"myth": "People with OCPD can't change.", "fact": "Therapy helps people loosen rules, tolerate imperfection, and reconnect with people and pleasure."}],
 {"plain": "OCPD is the most common personality disorder, affecting around 8 in 100 adults by US survey estimates, men a little more than women.", "figure": "About 7.9% of US adults (NESARC 2001–02, roughly 16.4 million)", "source_ref": "src-nesarc-pd"},
 {"plain_summary": "Cognitive-behavioural therapy adapted for OCPD, which targets perfectionism, rigid thinking, and the fear of mistakes, has growing evidence, along with schema therapy and psychodynamic approaches. Couples therapy often helps, since relationships bear the brunt. Medication isn't a treatment for OCPD, though co-occurring anxiety or depression may be treated, prescribed and monitored by a doctor. Learning to tolerate 'good enough' is the heart of it.",
  "evidence_based_options": ["CBT adapted for OCPD and perfectionism", "Schema therapy or psychodynamic therapy", "Couples or family therapy", "Treatment of co-occurring anxiety, depression, or OCD"],
  "self_help_that_supports_care": ["Deliberately doing one task to 'good enough' and stopping", "Scheduling leisure as seriously as work", "Letting someone else do a task their way, without correcting", "Asking the people close to you what the rules cost them"],
  "guideline_refs": ["src-nice-cg78"]},
 "If perfectionism and control are costing you relationships, health, or the ability to finish things, or if the people around you say so, a therapist experienced with personality difficulties can help. Burnout and depression are common and treatable.",
 "Being conscientious, organized, or principled isn't a disorder. OCD, with intrusive thoughts and rituals the person dislikes, is a different condition, though the two can co-occur.",
 "People with OCPD who loosen their grip often report something they'd forgotten: enjoying things.",
 ["about-personality-disorders", "obsessive-compulsive-disorder", "hoarding-disorder", "generalized-anxiety-disorder", "avoidant-personality-disorder"],
 ["perfectionism", "ocd-as-adjective", "burnout", "cbt", "schema-therapy"],
 PD_COMMS, ("Soft line illustration of a person leaving a slightly messy desk with a satisfied shrug to join friends at a picnic outside the window. Pastel plum and green.", "A person leaves a slightly messy desk with a satisfied shrug to join friends at a picnic outside."),
 [DSM_P, NESARC], qs=["Look for r/OCPD and verify."], cult="Cultures and professions that prize precision and duty can mask OCPD or make it look like excellence. The test is harm and inflexibility, not high standards."))
